import{_ as a,o as t,c as r,ah as s}from"./chunks/framework.BsNNkeaH.js";const u=JSON.parse('{"title":"Report cards","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/bulletins.md","filePath":"src/en/guide/admin/bulletins.md"}'),o={name:"en/guide/admin/bulletins.md"};function n(l,e,i,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="report-cards" tabindex="-1">Report cards <a class="header-anchor" href="#report-cards" aria-label="Permalink to &quot;Report cards&quot;">​</a></h1><p>This page covers publishing report cards on the administration side — once teachers have entered their grades and appreciations for a given period (which is their own job, not yours), you&#39;re the one who triggers generating and releasing the report cards.</p><h2 id="publish-a-class-s-report-cards" tabindex="-1">Publish a class&#39;s report cards <a class="header-anchor" href="#publish-a-class-s-report-cards" aria-label="Permalink to &quot;Publish a class&#39;s report cards&quot;">​</a></h2><p>From <strong>School setup → Classes</strong>, click <strong>Bulletins</strong> on the row for the class you want.</p><p>To publish:</p><ol><li>Choose the <strong>Academic period</strong> you want from the dropdown at the top of the page.</li><li>Click <strong>Publish / republish bulletins</strong>.</li></ol><p>This generates (or regenerates) every student&#39;s report card in the class for that period, based on the grades and appreciations already entered. Republishing after a grade correction updates the already-published report card — students and parents always see the latest version.</p><p>If no academic period is configured for this class&#39;s year, a message tells you so — go create one first in <a href="/en/guide/admin/structure-etablissement.html">School structure</a>.</p><h2 id="track-and-download-report-cards" tabindex="-1">Track and download report cards <a class="header-anchor" href="#track-and-download-report-cards" aria-label="Permalink to &quot;Track and download report cards&quot;">​</a></h2><p>The table below the period selector lists each student in the class with:</p><ul><li><strong>Status</strong> — &quot;Not published&quot;, or the date the report card was published.</li><li>A download button (icon), available as soon as a report card has been generated for that student.</li></ul><h2 id="report-card-template" tabindex="-1">Report card template <a class="header-anchor" href="#report-card-template" aria-label="Permalink to &quot;Report card template&quot;">​</a></h2><p>The visual template used (Classic, Compact, or Traditional French-style) is chosen per class, in the class&#39;s form — see <a href="/en/guide/admin/structure-etablissement.html#classes">School structure</a>. If no template is chosen for a class, the school&#39;s default template applies.</p>',13)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
